using EFootwear.BLL.Contacts.Contracts;

namespace EFootwear.BLL.Staff.Contracts;

/// <summary>
/// New Staff. The name and the phone number are required, and the person works in a store (StoreId). Designation, email, birth date and city
/// are optional. The code is generated by the server. Salary terms are managed by the payroll module; new staff start at 0.
/// </summary>
public sealed record CreateStaffMemberRequest(
    string Name,
    string? Phone,
    string? Email,
    DateOnly? BirthDate,
    Guid? CityId,
    string? Designation,
    bool IsManager,
    Guid? StoreId,
    string StatusCode,
    ContactOpeningBalanceRequest? OpeningBalance) : IStaffMemberEditableFields;
